class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        roof = m * n
        parent = list(range(roof + 1))
        sz = [1] * (roof + 1)
        sz[roof] = 0

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return
            if sz[px] > sz[py]:
                px, py = py, px
            parent[px] = py
            sz[py] += sz[px]

        def idx(i, j):
            return i * n + j

        for x, y in hits:
            grid[x][y] -= 1

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    if i == 0:
                        union(idx(i, j), roof)
                    for di, dj in dirs:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                            union(idx(i, j), idx(ni, nj))

        res = [0] * len(hits)
        for k in range(len(hits) - 1, -1, -1):
            x, y = hits[k]
            grid[x][y] += 1
            if grid[x][y] != 1:
                continue
            old = sz[find(roof)]
            if x == 0:
                union(idx(x, y), roof)
            for di, dj in dirs:
                ni, nj = x + di, y + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                    union(idx(x, y), idx(ni, nj))
            new = sz[find(roof)]
            res[k] = max(0, new - old - 1)
        return res
```

