from collections import deque

class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.tree = [0] * (n + 1)

    def update(self, i: int, delta: int) -> None:
        while i <= self.n:
            self.tree[i] += delta
            i += i & -i

    def query(self, i: int) -> int:
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s


class MKAverage:

    def __init__(self, m: int, k: int):
        self.m = m
        self.k = k
        self.MAX = 10 ** 5
        self.dq = deque()
        self.cnt = Fenwick(self.MAX)
        self.sm = Fenwick(self.MAX)

    def addElement(self, num: int) -> None:
        if len(self.dq) == self.m:
            old = self.dq.popleft()
            self.cnt.update(old, -1)
            self.sm.update(old, -old)
        self.dq.append(num)
        self.cnt.update(num, 1)
        self.sm.update(num, num)

    def _sum_smallest(self, p: int) -> int:
        if p == 0:
            return 0
        low, high = 1, self.MAX
        while low < high:
            mid = (low + high) // 2
            if self.cnt.query(mid) >= p:
                high = mid
            else:
                low = mid + 1
        val = low
        cnt_less = self.cnt.query(val - 1)
        sum_less = self.sm.query(val - 1)
        need = p - cnt_less
        return sum_less + need * val

    def calculateMKAverage(self) -> int:
        if len(self.dq) < self.m:
            return -1
        total = self.sm.query(self.MAX)
        small = self._sum_smallest(self.k)
        large = total - self._sum_smallest(self.m - self.k)
        mid_sum = total - small - large
        return mid_sum // (self.m - 2 * self.k)
```

