class Solution:
    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:
        def f(s: str) -> int:
            return s.count(min(s))

        counts = [0] * 12
        for w in words:
            counts[f(w)] += 1

        suffix = [0] * 12
        for i in range(10, 0, -1):
            suffix[i] = suffix[i + 1] + counts[i]

        return [suffix[f(q) + 1] for q in queries]
