class Solution:
    def maxTotalFruits(self, fruits: List[List[int]], startPos: int, k: int) -> int:
        n = len(fruits)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + fruits[i][1]

        def get_cost(i: int, j: int) -> int:
            left = min(fruits[i][0], startPos)
            right = max(fruits[j][0], startPos)
            return (right - left) + min(startPos - left, right - startPos)

        ans = 0
        i = 0
        for j in range(n):
            while i <= j and get_cost(i, j) > k:
                i += 1
            if i <= j:
                ans = max(ans, prefix[j + 1] - prefix[i])
        return ans
