            target = row_pre[r][c + k] - row_pre[r][c]
            for i in range(r, r + k):
                if row_pre[i][c + k] - row_pre[i][c] != target:
                    return False
            for j in range(c, c + k):
                if col_pre[j][r + k] - col_pre[j][r] != target:
                    return False
            s = 0
            for d in range(k):
                s += grid[r + d][c + d]
            if s != target:
                return False
            s = 0
            for d in range(k):
                s += grid[r + d][c + k - 1 - d]
            if s != target:
                return False
            return True

