        n = len(seats[0])
        # Precompute valid masks for each row
        valid = []
        for row in seats:
            mask = 0
            for j in range(n):
                if row[j] == '#':
                    mask |= (1 << j)
            # Generate all masks with no adjacent 1s
            masks = []
            def gen(cur, pos):
                if pos == n:
                    masks.append(cur)
                    return
                gen(cur, pos + 1)
                if pos == 0 or (cur & (1 << (pos - 1))) == 0:
                    gen(cur | (1 << pos), pos + 1)
            gen(0, 0)
            valid.append([m for m in masks if (m & mask) == 0])
        # DP
