    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        memo = {}
        def dp(l, mid, r):
            key = (l, mid, r)
            if key in memo:
                return memo[key]
            if l == r:
                res = (1, 1)
                memo[key] = res
                return res
            mtot = l + mid + r + 2
            def get_group(p):
                if p <= l:
                    return 'L'
                elif p == l + 1:
                    return 'A'
                elif p <= l + 1 + mid:
                    return 'M'
                elif p == l + mid + 2:
                    return 'B'
                else:
                    return 'R'
            forced = {'L': 0, 'M': 0, 'R': 0}
            mixed = []
            for i in range(1, mtot + 1):
                j = mtot + 1 - i
                if i > j:
                    break
                g1 = get_group(i)
                if i == j:
                    if g1 not in ('A', 'B'):
                        forced[g1] += 1
                    continue
                g2 = get_group(j)
                if g1 in ('A', 'B') or g2 in ('A', 'B'):
                    continue
                if g1 == g2:
                    forced[g1] += 1
                else:
                    mixed.append((g1, g2))
            possible = {(forced['L'], forced['M'], forced['R'])}
            for g1, g2 in mixed:
                new_possible = set()
                for cl, cm, cr in possible:
                    for g in (g1, g2):
                        if g == 'L':
                            new_possible.add((cl + 1, cm, cr))
                        elif g == 'M':
                            new_possible.add((cl, cm + 1, cr))
                        else:
                            new_possible.add((cl, cm, cr + 1))
                possible = new_possible
            minr = float('inf')
            maxr = 0
            for nl, nm, nr in possible:
                submin, submax = dp(nl, nm, nr)
                minr = min(minr, 1 + submin)
                maxr = max(maxr, 1 + submax)
            res = (minr, maxr)
            memo[key] = res
            return res
        l0 = firstPlayer - 1
        mid0 = secondPlayer - firstPlayer - 1
        r0 = n - secondPlayer
        ans = dp(l0, mid0, r0)
        return [ans[0], ans[1]]
