    def strWithout3a3b(self, a: int, b: int) -> str:
        s = []
        while a > 0 or b > 0:
            if a >= b:
                if len(s) >= 2 and s[-1] == ' a' and s[-2] == 'a':
                    s.append('b')
                    b -= 1
                else:
                    s.append('a')
                    a -= 1
            else:
                if len(s) >= 2 and s[-1] == 'b' and s[-2] == 'b':
                    s.append('a')
                    a -= 1
                else:
                    s.append('b')
                    b -= 1
